var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/companies/%7Bcompany_id%7D/project_stages"),
    Content = new StringContent("{\"project_stage\":{\"is_bidding_stage\":false,\"name\":\"Project Stage A\",\"category\":\"course_of_construction\"}}")
